import{c as a,Q as l,j as t,m as _}from"./chunks/framework.DOi4mjdC.js";const r=JSON.parse('{"title":"设置DCI编译选项来减少算子尾开销","description":"","frontmatter":{},"headers":[{"level":1,"title":"设置DCI编译选项来减少算子尾开销","slug":"设置dci编译选项来减少算子尾开销"}],"relativePath":"guide/算子实践参考/SIMD算子性能优化/头尾开销优化/设置DCI编译选项来减少算子尾开销.md","filePath":"guide/算子实践参考/SIMD算子性能优化/头尾开销优化/设置DCI编译选项来减少算子尾开销.md"}'),c={name:"guide/算子实践参考/SIMD算子性能优化/头尾开销优化/设置DCI编译选项来减少算子尾开销.md"};function C(n,e,i,o,d,s){return l(),t("div",null,[...e[0]||(e[0]=[_('<h1 id="设置dci编译选项来减少算子尾开销" tabindex="-1">设置DCI编译选项来减少算子尾开销 <a class="header-anchor" href="#设置dci编译选项来减少算子尾开销" aria-label="Permalink to &quot;设置DCI编译选项来减少算子尾开销&quot;">​</a></h1><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>该性能优化建议适用于如下型号：</p><ul><li>Ascend 950PR/Ascend 950DT</li></ul></div><p>【优先级】高</p><p>【描述】算子执行结束时，需要将DCache置为无效，防止后续算子继续使用DCache中的数据而受到影响。可以通过在编译选项中添加--cce-no-dcache-flush，用于在算子尾部增加DCI（DataCacheInvalid）指令来使DCache失效。如果不开启该选项，则会默认增加DCCI（DataCacheCleanAndInvalid）指令来使DCache失效。</p><p>插入DCI指令相比于插入DCCI指令，其减少了数据从DCache同步到GM（Clean）的过程，性能上会有一定优势。插入DCCI是一种额外的容错保证，如果开发者使用了* __gm__的方式改写GM内存，或者调用GlobalTensor.SetValue函数时，没有正确的调用DataCacheCleanAndInvalid接口来保证Cache一致性，编译框架自动插入DCCI恰好可以保证算子精度正常。</p><p>所以在如下场景，可以通过开启该编译选项来降低算子尾部开销：</p><ul><li>算子使用* __gm__的方式改写GM内存，或者调用GlobalTensor.SetValue函数时，正确的使用DataCacheCleanAndInvalid接口，手动将数据从DCache中回刷到GM上，保证Cache的一致性。不依赖编译框架自动插入DCCI指令来保证一致性。</li><li>算子不包含使用* __gm__的方式改写GM内存，或者调用GlobalTensor.SetValue函数的代码。</li></ul>',7)])])}const I=a(c,[["render",C]]);export{r as __pageData,I as default};
